class Held(Exception):
    def __init__(self, code):
        self.code = code


def safe_exception_type(error):
    name=type(error).__name__
    return name if name in {'Held','Error','TimeoutError','TargetClosedError','ValueError','TypeError',
        'KeyError','AttributeError','OSError','ExtractionError','UnicodeDecodeError','RuntimeError'} else 'Exception'


def blocked_request_classification(url,method,resource_type,main_frame):
    """Fixed enums only: never retain origin names, paths, queries or bodies."""
    origin,path='invalid','invalid'
    try:
        parts=urlsplit(url)
        if parts.username is not None or parts.password is not None or parts.port not in (None,443):
            origin='invalid_authority'
        elif parts.scheme=='https' and parts.hostname in {'4over.com','www.4over.com'}:
            origin='source'
        else:origin='external'
        value=parts.path
        if value==urlsplit(SOURCE).path:path='product_document'
        elif '/product/prices/' in value:path='child_price'
        elif value==SUMMARY:path='project_summary'
        elif value.startswith('/print/shipment/'):path='shipping'
        elif value.startswith(('/checkout/cart/','/cart/')) or re.match(r'^/rest/(?:default/)?V1/(?:carts|guest-carts)(?:/|$)',value):path='cart'
        elif value.startswith('/checkout/'):path='checkout'
        elif value.startswith(('/sales/order/','/order/')):path='order'
        elif value.startswith(('/upload/','/print/upload/','/media/upload/')):path='upload'
        elif value.startswith('/customer/'):path='account'
        elif value==TRACKER_PATH:path='source_telemetry'
        elif value.startswith('/static/'):path='static_asset'
        elif value.startswith('/media/'):path='media_asset'
        else:path='other'
    except (ValueError,TypeError):pass
    return {'origin_class':origin,'path_class':path,
        'method_class':method if method in {'GET','POST','PUT','PATCH','DELETE','HEAD','OPTIONS'} else 'OTHER',
        'resource_type':resource_type if resource_type in {'document','stylesheet','image','media','font','script',
            'texttrack','xhr','fetch','eventsource','websocket','manifest','other'} else 'other',
        'main_frame':main_frame is True}


class _StaticScriptParser(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.roles={role:[] for role in STATIC_SCRIPT_ROLES}
        self.prefixes=set()
        self.invalid=False
        self.inert=[]
    def handle_starttag(self,tag,attrs):
        if tag.lower()=='plaintext':self.invalid=True;return
        if tag.lower() in {'template','noscript','textarea','title','xmp','iframe','noembed','noframes','svg','math'}:
            self.inert.append(tag.lower());return
        if tag.lower()!='script' or self.inert:return
        values={}
        for name,value in attrs:values.setdefault(name,[]).append(value)
        sources=values.get('src',[])
        for src in sources:
            if not isinstance(src,str):continue
            role=next((r for r in STATIC_SCRIPT_ROLES if src.endswith('/'+r)),None)
            canonical=re.fullmatch('('+STATIC_PREFIX_PATTERN+r')([^?#]+)',src)
            if canonical:self.prefixes.add(canonical.group(1))
            if role is None:continue
            if (len(sources)!=1 or 'nomodule' in values or 'language' in values or len(values.get('type',[]))>1
                    or values.get('type',['text/javascript'])[0] not in ('text/javascript','application/javascript',None,'')
                    or '&' in (self.get_starttag_text() or '')
                    or not re.fullmatch(STATIC_PREFIX_PATTERN+re.escape(role),src)):
                self.invalid=True
            self.roles[role].append(src)
    def handle_endtag(self,tag):
        if self.inert and tag.lower()==self.inert[-1]:self.inert.pop()
        elif tag.lower() in self.inert:self.invalid=True
    def handle_startendtag(self,tag,attrs):
        # HTML does not close nonvoid script/template elements with '/>'.
        if tag.lower() in {'script','plaintext'}:self.invalid=True
        elif tag.lower() in {'template','noscript','textarea','title','xmp','iframe','noembed','noframes','svg','math'}:
            self.handle_starttag(tag,attrs)


def document_static_prefix(raw):
    """Only coherent canonical executable script declarations establish a prefix.

    Called after all705 declarations and exact option rows are validated. This
    parser reads no account/contact values and never returns arbitrary paths.
    """
    if not isinstance(raw,bytes) or len(raw)>LIMIT:raise Held('source_static_prefix_unavailable')
    try:
        parser=_StaticScriptParser();parser.feed(raw.decode('utf-8'));parser.close()
    except (UnicodeDecodeError,ValueError,TypeError):raise Held('source_static_prefix_unavailable') from None
    if parser.invalid or any(len(v)!=1 for v in parser.roles.values()) or len(parser.prefixes)!=1:
        raise Held('source_static_prefix_unavailable')
    prefix=next(iter(parser.prefixes))
    if any(parser.roles[role][0]!=prefix+role for role in STATIC_SCRIPT_ROLES):
        raise Held('source_static_prefix_unavailable')
    return prefix


def static_xhr_asset_id(url, method, resource_type, main_frame, declared_prefix=None, *, assets_only=False):
    """Exact source-declared prefix + observed suffix, with no URL variants."""
    if method!='GET' or resource_type!='xhr' or main_frame is not True:return None
    if not isinstance(declared_prefix,str) or not re.fullmatch(STATIC_PREFIX_PATTERN,declared_prefix):return None
    if not isinstance(url,str) or not url.startswith(declared_prefix):return None
    suffix=url[len(declared_prefix):]
    return STATIC_XHR_IDS.get(suffix) or (BOOTSTRAP_XHR_IDS.get(suffix) if assets_only is True else None)


def static_xhr_classification(url, declared_prefix):
    """Bounded public-version metadata and fixed enums; no raw paths/queries."""
    result={'prefix_class':'noncanonical_static','static_version':None,'asset_id':None,
            'query_present':False,'fragment_present':False}
    try:
        parts=urlsplit(url)
        result.update(query_present='?' in url.split('#',1)[0],fragment_present='#' in url)
        if parts.scheme!='https' or parts.netloc!='4over.com':return result
        match=re.fullmatch(r'/static/version([1-9][0-9]{0,19})/frontend/FourOver/default/en_US/(.+)',parts.path)
        if not match:return result
        version,suffix=match.groups();result['static_version']=version
        result['asset_id']=ALL_STATIC_XHR_IDS.get(suffix)
        prefix='https://4over.com/static/version'+version+'/frontend/FourOver/default/en_US/'
        result['prefix_class']=('prefix_not_validated' if declared_prefix is None else
            'other_version' if prefix!=declared_prefix else
            'observed_suffix' if result['asset_id'] is not None else 'unobserved_suffix')
    except (ValueError,TypeError):pass
    return result


class _BootstrapHTMLFragment(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True);self.elements=0;self.document=False
    def handle_starttag(self,tag,attrs):
        self.elements+=1
        if tag.lower() in {'html','head','body'}:self.document=True
    handle_startendtag=handle_starttag
    def handle_decl(self,decl):self.document=True


def bootstrap_static_body_metadata(asset_id,body,*,generic_template=False):
    """Validate only the five newly admitted PUBLIC dependencies; no body saved.

    Original24 template validation is unchanged. All responses still obey the
    same byte/aggregate bounds before this function is called.
    """
    if type(asset_id) is not int or not (asset_id in range(1,30) or (generic_template is True and 30<=asset_id<=ASSET_DIAGNOSIS_STATIC_LIMIT)):
        raise Held('native_static_asset_response_unavailable')
    if asset_id<=24:return {}
    if not isinstance(body,bytes) or len(body)>STATIC_XHR_MAX_RESPONSE:
        raise Held('native_static_asset_response_unavailable')
    try:
        text=body.decode('utf-8')
        if asset_id==25:
            value=json.loads(text,object_pairs_hook=_unique_object)
            if type(value) is list and not value:
                return {'response_mime':'application/json','body_validation':'bounded_string_dictionary',
                        'dictionary_entries':0,'dictionary_representation':'empty_array'}
            if (type(value) is not dict or len(value)>STATIC_JSON_MAX_ENTRIES
                    or any(type(k) is not str or type(v) is not str
                        or len(k)>STATIC_JSON_MAX_TEXT_CHARS or len(v)>STATIC_JSON_MAX_TEXT_CHARS
                        for k,v in value.items())):
                raise ValueError()
            return {'response_mime':'application/json','body_validation':'bounded_string_dictionary',
                    'dictionary_entries':len(value),'dictionary_representation':'object'}
        parser=_BootstrapHTMLFragment();parser.feed(text);parser.close()
        if not parser.elements or parser.document:raise ValueError()
        return {'response_mime':'text/html','body_validation':'bounded_html_fragment'}
    except (UnicodeDecodeError,ValueError,TypeError,RecursionError):
        raise Held('native_static_asset_body_unavailable') from None


PUBLIC_ROOT_STATIC_FILES = frozenset({'js-translation.json','requirejs-config.js'})
PUBLIC_SHARED_STATIC_ROOTS = frozenset({'mage','requirejs','jquery','jquery-ui-modules','js','css','lib'})
PUBLIC_COMPONENT_DIRECTORIES = frozenset({'template','templates','js','css'})


def public_static_relative_path(url,declared_prefix):
    """Logging only: canonical public code filenames, never request admission.

    Root translation dictionary is an explicitly permitted PUBLIC filename for
    diagnosis only. No response/content, arbitrary root filename or identifier
    is exposed. The original exact24 GET/XHR allowlist remains unchanged.
    """
    if (not isinstance(url,str) or not isinstance(declared_prefix,str)
            or not re.fullmatch(STATIC_PREFIX_PATTERN,declared_prefix)
            or not url.startswith(declared_prefix)):
        return None,'not_validated_prefix'
    suffix=url[len(declared_prefix):]
    if '?' in suffix or '#' in suffix:return None,'query_or_fragment'
    if not 1<=len(suffix)<=256:return None,'path_length'
    if not suffix.isascii() or re.search(r'[^A-Za-z0-9_./-]',suffix):return None,'noncanonical_characters'
    segments=suffix.split('/')
    if any(part in {'','.','..'} for part in segments):return None,'unsafe_segments'
    if not re.fullmatch(r'[A-Za-z][A-Za-z0-9_-]*(?:\.[A-Za-z][A-Za-z0-9_-]*){0,2}\.(?:js|json|html|css)',segments[-1]):
        return None,'unsupported_file_grammar'
    if (re.search(r'(?:^|[-_./])(?:private|token|session|password|passwd|secret|credential|authorization|email|formkey)(?:$|[-_./])',suffix,re.I)
            or any(re.fullmatch(r'[a-fA-F0-9]{16,}(?:\.(?:js|json|html|css))?',part)
                   or re.fullmatch(r'[a-fA-F0-9]{8}(?:-[a-fA-F0-9]{4}){3}-[a-fA-F0-9]{12}(?:\.(?:js|json|html|css))?',part) for part in segments)):
        return None,'private_identifier'
    if len(segments)==1:
        return (suffix,None) if suffix in PUBLIC_ROOT_STATIC_FILES else (None,'unrecognized_root_file')
    if any(not re.fullmatch(r'[A-Za-z][A-Za-z0-9_-]{0,63}',part) for part in segments[:-1]):
        return None,'unsupported_segment_grammar'
    component=bool(re.fullmatch(r'(?:Magento|FourOver)_[A-Z][A-Za-z0-9]{0,63}',segments[0]))
    if component:
        if len(segments)<3 or segments[1] not in PUBLIC_COMPONENT_DIRECTORIES:return None,'unsupported_component_directory'
    elif segments[0] not in PUBLIC_SHARED_STATIC_ROOTS:return None,'unrecognized_component'
    return suffix,None


def generic_public_template_suffix(url,declared_prefix):
    """A SOURCE-PAGE-generated static HTML template, never arbitrary GET data."""
    suffix,redaction=public_static_relative_path(url,declared_prefix)
    if redaction is not None or suffix is None or not suffix.endswith('.html'):return None
    parts=suffix.split('/')
    component=bool(re.fullmatch(r'(?:Magento|FourOver)_[A-Z][A-Za-z0-9]{0,63}',parts[0]))
    if component and len(parts)>=3 and parts[1] in {'template','templates'}:return suffix
    if len(parts)>=3 and parts[:2]==['mage','gallery']:return suffix
    return None


