def attributes_retained(state, *, visible=False, selection=None):
    selection=selection or {'child_id':CHILD,'run_size':RUN_SIZE,'attributes':VALUES}
    return state.get('child_id') == selection['child_id'] and all(
        state.get('attributes',{}).get(k,{}).get('count') == 1
        and state['attributes'][k].get('value') == value
        and state['attributes'][k].get('enabled') is True
        and (not visible or state['attributes'][k].get('visible') is True or state['attributes'][k].get('implicit_fixed_dash') is True)
        and state['attributes'][k].get('choice_enabled') is True for k,value in selection['attributes'].items())


def services_off(state):
    return all(state.get('services',{}).get(k) == {'count':1,'checked':False,'enabled':True} for k in ('job_sample','digital_proof'))


def context_retained(state, *, final=False, selection=None):
    selection=selection or {'child_id':CHILD,'run_size':RUN_SIZE,'attributes':VALUES}
    if not attributes_retained(state,visible=True,selection=selection) or state.get('run_size') != str(selection['run_size']) or not services_off(state):
        return False
    sets = state.get('sets')
    return (not final and sets is None) or (sets is not None and sets.get('value') == '1' and sets.get('valid') is True and sets.get('enabled') is True)


def request_context(post_data,state,*,selection=None):
    """Project only exact product fields; never retain address/UUID/form-key data."""
    selection=selection or {'child_id':CHILD,'run_size':RUN_SIZE,'attributes':VALUES}
    values_expected=selection['attributes']
    if not isinstance(post_data,str) or len(post_data.encode()) > 65536 or not context_retained(state,selection=selection):
        raise Held('native_summary_context_missing')
    try:
        pairs = parse_qsl(post_data,keep_blank_values=True,strict_parsing=True,max_num_fields=256)
    except ValueError:
        raise Held('native_summary_schema_unavailable') from None
    values = {}
    for key,value in pairs:
        values.setdefault(key,[]).append(value)
    def one(key):
        rows = values.get(key,[])
        if len(rows) != 1:
            raise Held('native_summary_context_missing')
        return rows[0]
    option_keys = {f'product_options[super_attribute][{k}]' for k in values_expected}
    if {k for k in values if k.startswith('product_options[super_attribute]')} != option_keys:
        raise Held('native_summary_options_changed')
    if any(one(f'product_options[super_attribute][{k}]') != v for k,v in values_expected.items()):
        raise Held('native_summary_options_changed')
    product_id = one('product_id')
    if product_id not in set(state.get('parent_ids',[])) | {selection['child_id']} or one('run_size') != str(selection['run_size']) or one('custom_run_size') != '0':
        raise Held('native_summary_run_size_changed')
    for name in ('job_sample','digital_proof'):
        for key in (name,f'product_options[{name}]'):
            if key in values and one(key) not in {'','0','false','off'}:
                raise Held('native_summary_services_changed')
    explicit_sets = [key for key in ('sets','qty','quantity') if key in values]
    jobs = {m.group(1,2) for key in values if (m:=re.match(r'^shipments\[(\d+)\]\[jobs\]\[(\d+)\]',key))}
    if any(one(k) != '1' for k in explicit_sets) or jobs and jobs != {('0','0')}:
        raise Held('native_summary_sets_changed')
    for key in values:
        if re.fullmatch(r'shipments\[0\]\[jobs\]\[0\]\[(?:qty|quantity|sets)\]',key) and one(key) != '1':
            raise Held('native_summary_sets_changed')
    if not explicit_sets and jobs != {('0','0')}:
        raise Held('native_summary_set_binding_missing')
    production = state.get('production')
    if (not production or not re.fullmatch(r'[0-9]{1,6}',production.get('value',''))
            or not re.search(r'\b(?:business\s+days?|days?|hours?)\b',production.get('label',''),re.I)
            or one('product_options[turnaround_time]') != production['value']):
        raise Held('native_production_unavailable')
    return {'product_id':product_id,'child_id':selection['child_id'],'attributes':dict(values_expected),'run_size':selection['run_size'],'sets':1,
            'services':SCOPE,'production':{'value':production['value'],'label':production['label']},
            'set_binding':'explicit_one' if explicit_sets else 'one_native_job'}


def parse_summary(raw):
    try:
        value = json.loads(raw,parse_float=Decimal,parse_int=Decimal,object_pairs_hook=_unique_object,
                           parse_constant=lambda _: (_ for _ in ()).throw(ValueError()))
        totals = value['totals']
        allowed = {'subtotal','grand_total','small_qty_fee','turnaround_time','job_sample','digital_proof'}
        if not isinstance(totals,dict) or set(totals)-allowed:
            raise ValueError()
        result = {}
        for key in allowed:
            item = totals.get(key)
            if item is None and key not in {'subtotal','grand_total'}:
                amount = Decimal(0)
            else:
                if isinstance(item,bool):raise ValueError()
                amount = Decimal(str(item))
            if (not amount.is_finite() or amount < 0 or amount.as_tuple().exponent < -2
                    or amount.adjusted()>12 or len(amount.as_tuple().digits)>24):
                raise ValueError()
            result[key] = amount
        if result['subtotal'] <= 0 or result['job_sample'] or result['digital_proof']:
            raise ValueError()
        if result['grand_total'] != sum((v for k,v in result.items() if k != 'grand_total'),Decimal(0)):
            raise ValueError()
        return {k:format(v,'.2f') for k,v in result.items()}
    except (ValueError,KeyError,TypeError,ArithmeticError):
        raise Held('native_summary_total_unavailable') from None


def bounded_prices(raw):
    """Bound numeric expansion before the shared exact-decimal parser formats it."""
    try:
        value=json.loads(raw,parse_float=Decimal,parse_int=Decimal,object_pairs_hook=_unique_object,
                         parse_constant=lambda _: (_ for _ in ()).throw(ValueError()))
        if not isinstance(value,list) or len(value)!=1 or not isinstance(value[0],dict):raise ValueError()
        for name in ('packagePrices','tierPrices'):
            rows=value[0].get(name,[])
            if not isinstance(rows,list) or len(rows)>1000:raise ValueError()
            for row in rows:
                if not isinstance(row,dict):raise ValueError()
                for field in ('qty','price'):
                    number=row.get(field)
                    if (not isinstance(number,Decimal) or not number.is_finite() or number<=0
                            or number.adjusted()>12 or number.as_tuple().exponent < -18
                            or len(number.as_tuple().digits)>36):raise ValueError()
        return parse_positive_prices(raw)
    except (ValueError,TypeError,ArithmeticError,ExtractionError):
        raise Held('native_package_price_unavailable') from None


